mkdir -p /tmp/millkit3-tools && cat > /tmp/millkit3-tools/dump.mjs <<'EOF'
// Usage: node dump.mjs build.nbt x0 x1 y0 y1 z0 z1  -> prints non-air cells in the box
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [file, x0, x1, y0, y1, z0, z1] = process.argv.slice(2);
const g = load(file);
for (let y = +y0; y <= +y1; y++)
  for (let z = +z0; z <= +z1; z++)
    for (let x = +x0; x <= +x1; x++) {
      const b = g.get(x, y, z);
      if (b && !/air$/.test(b.block)) console.log(`${x},${y},${z} ${b.block}${b.state ? " " + JSON.stringify(b.state) : ""}`);
    }
EOF
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit3 && node /tmp/millkit3-tools/dump.mjs build.nbt 47 54 0 4 4 9 2>&1 | head -150

