  g.set(43, 3, 15, "barrel", { facing: "up", open: "false" });
  g.set(43, 4, 15, "flower_pot", {});
  // A flower pot on the table, the dining room's centre piece.
  g.set(40, 5, 14, "flower_pot", {});
