    // partitions z13 (x86..87 and x92..93), doors at x86 and x93, both storeys
    wl(86, 3, 13, 87, 6, 13, solid(W), [[86, 3, 13, 86, 4, 13]]);
    wl(92, 3, 13, 93, 6, 13, solid(W), [[93, 3, 13, 93, 4, 13]]);
    wl(86, 8, 13, 87, 11, 13, solid(W), [[86, 8, 13, 86, 9, 13]]);
