  // plot 3 tower: pyramid cap of copper over the stage top y15, eave y16, apex ~y22
  roof(g, [[43, 7, 46, 10]], "pyramid", { pitch: 45, y: 16, edges: EDGES, trim: "birch_planks", overhang: 1, material: COPPER });
