// P7 gallery: a sleeping porch on the upper deck, two units divided by the brick pier x89..90.
// Inner air box [85,8,7, 94,10,8]. Each unit has its own gallery door (x88 and x91, z9, y8..9); the cells in front
// of them (x88 z8, x91 z8) stay clear. Per unit: one bed with its head against the house wall (z9, y8), a barrel
// nightstand with a flower pot, a chair on the front edge, and a hanging lantern. The bed heads sit against solid
// wall cells, never a window (the windows are at y9..10 on z9).
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { chair, hanging_lantern, bed_set } from "../vocab.mjs";

export function build(g) {
  // Row z8 (the room's back row, against the house wall): barrel nightstands at x85 and x94.
  layers(g, [85, 8, 8], { B: ["barrel", { facing: "up" }] }, [
    ["B        B"],
  ]);
  // Flower pots on top of the nightstands (y9, a full block below them).
  layers(g, [85, 9, 8], { P: "flower_pot" }, [
    ["P        P"],
  ]);
  // Beds: west unit (red) and east unit (orange). Foot on z7, head on z8 against the house wall at z9.
  bed_set(g, [86, 8, 7], "south", "red");
  bed_set(g, [93, 8, 7], "south", "orange");
  // Chairs on the front edge, sitters look north over the lane.
  chair(g, 87, 8, 7, "north");
  chair(g, 92, 8, 7, "north");
  // Lanterns hang from the roof over each unit, clear of the doorways (x88, x91).
  hanging_lantern(g, 87, 10, 8);
  hanging_lantern(g, 92, 10, 8);
}
----- room-26
// P3 belvedere: open glazed lookout under the copper cap. Inner air x 44..45, y 13..15, z 8..9.
// The ladder comes up through the hatch at (44,12,9) into (44,13,9). The room is only 2x2, so the layout is
// a lookout lantern on a birch post in the NE corner (the focal piece, lit from above the post) and one stair
// seat facing the east window. The entry cell and the path (44,8) stay clear.
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { chair } from "../vocab.mjs";

export function build(g) {
  // focal piece: a birch post in the NE corner with a standing lantern on top, looking out over both glazed walls
  g.set(45, 13, 8, ...B.fence("birch"));
  g.set(45, 14, 8, ...B.lantern(false));
  // seat: spruce stair in the SE cell, sitter facing east toward the east window (stair back on the west)
  chair(g, 45, 13, 9, "east");
}
----- room-45
// P7 east bedroom back: upper back bedroom, bed head on the east wall (x 94). Inner air x 92..93, z 14..15, y 8..11.
// Entered through the door at (93, 8..9, 13) onto (93, 8, 14), which stays clear. The bed runs east-west along z 15
// (foot (92, 8, 15), head (93, 8, 15) against the east wall). A barrel dresser stands in the back corner at (92, 8, 14)
// with a lantern on its top face, the room's one light.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // The bed: foot at x 92, head one step east against the solid east wall.
  bed(g, [92, 8, 15], "east", "orange");

  // Dresser and its lantern, drawn as text. Rows run along +x, successive rows along +z (z 14 then z 15).
  // y 8: barrel (open top, facing up) at (92, 8, 14); the bed cells and the door cell stay as they are.
  layers(g, [92, 8, 14], { B: ["barrel", { facing: "up" }] }, [
    ["B."],
  ]);
  // y 9: standing lantern on the barrel top (hanging false, so it stands on the barrel).
  layers(g, [92, 9, 14], { L: ["lantern", { hanging: "false" }] }, [
    ["L."],
  ]);
}

